```cpp
unsigned int instruction_length_offset = start_offset + GlyphHeader::static_size + 2 * num_contours;
if (unlikely (instruction_length_offset + 2 > end_offset))
{
  ...
  return false;
}
const HBUINT16 &instruction_length = StructAtOffset<HBUINT16> (glyf_table, instruction_length_offset);
unsigned int start = instruction_length_offset + 2;
unsigned int end = start + (uint16_t) instruction_length;
if (unlikely (end > end_offset))
{
  ...
  return false;
}
*instruction_start = start;
*instruction_end = end;
```

This reads HBUINT16. Not 8.

Let me reconsider. Maybe the READ 8 is in the `_update_components` function. Let me look at it again:

```cpp
static void
_update_components (hb_subset_plan_t * plan,
                    char * glyph_start,
                    unsigned int length)
{
  OT::glyf::CompositeGlyphHeader::Iterator iterator;
  if (OT::glyf::CompositeGlyphHeader::get_iterator (glyph_start,
                                                    length,
                                                    &iterator))
  {
    do
    {
      hb_codepoint_t new_gid;
